import re
import time

from moler.cmd.unix.genericunix import GenericUnixCommand

cmd_failure_causes = [r"nc: command not found$", r"Permission denied$", r"^invalid local port", r"^Ncat: Got more than one port specification"]

r_cmd_failure_cause_alternatives = ('|'.join(i for i in cmd_failure_causes))


class StartSyslog(GenericUnixCommand):
    """Startsyslog command class."""

    def __init__(
        self,
        connection,
        syslog_command=r"nc -luvp 51000 | sed 's/\x00//'",
        prompt=None,
        newline_chars=None,
        runner=None,
        time_for_failure=0.1,
        inactivity_timeout=10.0,
    ):
        """
        Startsyslog command.

        :param connection: Moler connection to device, terminal when command is executed.
        :param syslog_command: Unix options of nc command.
        :param prompt: prompt (on system where command runs).
        :param newline_chars: Characters to split lines - list.
        :param runner: Runner to run command.
        :param time_for_failure: time (in seconds) for failure indication from first line of output. Set to 0 if skip
        all failure indications.
        :param inactivity_timeout: time (in seconds) when no data is sent by connection within this time then command
        will be break
        """
        super(StartSyslog, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.syslog_command = syslog_command
        self.ret_required = False
        self.time_for_failure = time_for_failure
        self._first_line_time = None
        self._check_failure_indication = True
        self.life_status.inactivity_timeout = inactivity_timeout
        self.re_fail = re.compile(r_cmd_failure_cause_alternatives, re.IGNORECASE)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"{self.syslog_command}"

        return cmd

    def on_inactivity(self):
        """
        Call when no data is received on connection within self.life_status.inactivity_timeout seconds.

        :return: None
        """
        self.logger.info(f"No data in '{self.life_status.inactivity_timeout:.2f}' seconds.")
        self.break_cmd()

    def on_new_line(self, line, is_full_line):
        """
        Parse line from command output.

        :param line: Line from device
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            if not self._first_line_time:
                self._first_line_time = time.monotonic()
        super(StartSyslog, self).on_new_line(line=line, is_full_line=is_full_line)

    def is_failure_indication(self, line, is_full_line):
        """
        Check if line has info about failure indication.

        :param line: Line from device
        :param is_full_line: True if line had new line chars, False otherwise
        :return: False if line does not match regex with failure, True if line matches the failure regex.
        """
        if self._check_failure_indication:
            if not self._first_line_time:
                self._first_line_time = time.monotonic()
            if time.monotonic() - self._first_line_time < self.time_for_failure:
                return self._regex_helper.search_compiled(self.re_fail, line) is not None
            else:
                self._check_failure_indication = False  # do not check time for future output. It's too late already.
        return False


